$ErrorActionPreference = "Stop"

$projectRoot = (Get-Location).Path
$packagePath = Join-Path $projectRoot "package.json"
$targetDir = Join-Path $projectRoot "scripts\entity"
$targetPath = Join-Path $targetDir "test-emet-reader-explanation.js"
$backupRoot = Join-Path $projectRoot ".private\entity\backups"
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupDir = Join-Path $backupRoot "P04-reader-test-$stamp"

if (-not (Test-Path $packagePath)) {
    throw "Run this installer from the ai-bible-app project root. package.json was not found."
}

New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
New-Item -ItemType Directory -Force -Path $backupDir | Out-Null

if (Test-Path $targetPath) { Copy-Item $targetPath (Join-Path $backupDir "test-emet-reader-explanation.js") }
Copy-Item $packagePath (Join-Path $backupDir "package.json")

$payload = ""
[System.IO.File]::WriteAllBytes($targetPath, [Convert]::FromBase64String($payload))

$package = Get-Content $packagePath -Raw -Encoding UTF8 | ConvertFrom-Json
if (-not $package.scripts) {
    $package | Add-Member -NotePropertyName scripts -NotePropertyValue ([pscustomobject]@{})
}
$scriptCommand = "node --max-old-space-size=4096 scripts/entity/test-emet-reader-explanation.js"
if ($package.scripts.PSObject.Properties.Name -contains "test:emet-reader") {
    $package.scripts."test:emet-reader" = $scriptCommand
} else {
    $package.scripts | Add-Member -NotePropertyName "test:emet-reader" -NotePropertyValue $scriptCommand
}
$package | ConvertTo-Json -Depth 100 | Set-Content $packagePath -Encoding UTF8

node --check $targetPath
if ($LASTEXITCODE -ne 0) { throw "Reader-first test script failed JavaScript syntax validation." }

Write-Host ""
Write-Host "P04 reader-first review test installed successfully." -ForegroundColor Green
Write-Host "Backup: $backupDir"
Write-Host ""
Write-Host "This does not change the production P04 prompt or generation state."
Write-Host ""
Write-Host "Next command:"
Write-Host 'npm run test:emet-reader -- --entity word:hebrew:H1077' -ForegroundColor Cyan
